(101, 1, '2026-06-01 23:52:18', '2026-06-01 23:52:18', '<!-- wp:group {\"metadata\":{\"name\":\"Hero container\",\"categories\":[\"hero\"],\"patternName\":\"a8c/store-hero-2\"},\"align\":\"full\",\"style\":{\"dimensions\":{\"minHeight\":\"\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns alignwide are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"540px\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong>Onlajn komunikacija i društvo</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><em>Kako digitalne tehnologije mijenjaju naše odnose, socijalizaciju i svakodnevni život — analiza globalnih trendova s fokusom na Bosnu i Hercegovinu.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--20)\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/statistike/\">Istraži temu</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline \"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/anketa/\">Učestvuj u anketi</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"id\":69,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/camilo-jimenez-qzeno_gq7qa-unsplash.jpg\" alt=\"\" class=\"wp-image-69\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"overlayColor\":\"base\",\"isUserOverlayColor\":true,\"contentPosition\":\"top center\",\"isDark\":false,\"align\":\"wide\",\"style\":{\"color\":{\"duotone\":[\"#b5bdbc\",\"#B5BDBC\"]}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover alignwide is-light has-custom-content-position is-position-top-center\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-base-background-color has-background-dim-100 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#b5bdbc\",\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top has-border-color\" style=\"border-color:#b5bdbc;border-width:1px;border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>O projektu</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Saznaj više o ciljevima istraživanja, metodologiji i autorima projekta.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/o-projektu/\">Saznaj više</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#b5bdbc\",\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}}} -->\n<div class=\"wp-block-column has-border-color\" style=\"border-color:#b5bdbc;border-width:1px;border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>BiH kontekst</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Lokalni podaci o korištenju interneta i specifičnosti digitalnog društva u BiH.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-fill\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/mywordpress/bih-kontekst/\">Istraži</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}},\"border\":{\"width\":\"1px\",\"color\":\"#b5bdbc\",\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}}} -->\n<div class=\"wp-block-column has-border-color\" style=\"border-color:#b5bdbc;border-width:1px;border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Zanimljivosti</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Neočekivane statistike i fascinantni fakti o internetu i društvenim mrežama.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/zanimljivosti/\">Otkrij</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->', 'Početna', '', 'inherit', 'closed', 'closed', '', '39-revision-v1', '', '', '2026-06-01 23:52:18', '2026-06-01 23:52:18', '', 39, 'http://localhost/mywordpress/?p=101', 0, 'revision', '', 0),
(102, 1, '2026-06-02 00:12:42', '2026-06-02 00:12:42', '<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong><em>Zanimljivosti o internetu u BiH</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-1\"} -->\n<div class=\"wp-block-columns alignwide has-gradient-1-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>BiH i dijaspora online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\",\"className\":\"is-style-default\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity is-style-default\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Procjenjuje se da van BiH živi više od 1,3 miliona Bosanaca. Većina njih ostaje u kontaktu s domovinom isključivo putem Facebooka i WhatsAppa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Facebook stariji od TikToka za cijelu generaciju</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Prosječni Facebook korisnik u BiH ima između 30 i 45 godina. Prosječni TikTok korisnik ima između 16 i 24. To su bukvalno dvije različite generacije na dva različita interneta.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Vijesti? Na Facebooku.</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Više od 60% građana BiH primarno se informiše putem društvenih mreža, a ne tradicionalnih medija. Facebook je danas važniji od večernjih vijesti.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":90,\"aspectRatio\":\"16/9\",\"scale\":\"cover\",\"focalPoint\":{\"x\":0.51,\"y\":0.51},\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/sumup-aqc7znjxrom-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-90\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px;aspect-ratio:16/9;object-fit:cover;object-position:51% 51%\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong><em>Globalne zanimljivosti o internetu</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-2\"} -->\n<div class=\"wp-block-columns alignwide has-gradient-2-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"width\":\"25%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Internet je mlađi nego što misliš</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>World Wide Web dostupan je javnosti tek od 1991.<br>Cijela era društvenih mreža stara je manje od 35 godina.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Svake minute na internetu…</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Svake minute šalje se oko 300 miliona emailova,<br>objavljuje 500 sati YouTube videa i pošalje<br>preko 41 milion WhatsApp poruka.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Više od polovine čovječanstva online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right\"><em>2024 godine više od 5,4 milijarde ljudi koristilo je internet - to je oko 67% ukupne svjetske populacije. Još prije 20 godina taj broj bio je ispod 15%.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":92,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/firmbee-com-dfmmzzi3rmg-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-92\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong><em>Društvene mreže</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-1\"} -->\n<div class=\"wp-block-columns alignwide has-gradient-1-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><em><strong>TikTok algoritam zna bolje od tebe</strong></em></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>TikTok može predvidjeti tvoje interese nakon samo<br>nekoliko minuta gledanja. Algoritam analizira čak<br>i to koliko dugo zastaneš na određenom videu.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><strong><em>Prosječan čovjek provede 6+ sati online dnevno</em></strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Od toga gotovo 2,5 sata otpada na društvene mreže.<br>U toku jedne godine to je više od 900 sati -<br>ili cijela 37 dana neprekidnog skrolanja.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><strong><em>YouTube je druga najveća tražilica na svijetu</em></strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Odmah iza Googlea — koji, usput, posjeduje YouTube.<br>Više ljudi traži upute i odgovore na YouTubeu<br>nego na Bingu, Yahoou i svim ostalima zajedno.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Zanimljivosti', '', 'inherit', 'closed', 'closed', '', '44-revision-v1', '', '', '2026-06-02 00:12:42', '2026-06-02 00:12:42', '', 44, 'http://localhost/mywordpress/?p=102', 0, 'revision', '', 0),
